"""Exact endpoint affine fit and a rational DDA-shaped trajectory proposal.

This module does NOT solve general affine-motion first contact or certify the
unknown physical path. See docs/m5a2_affine_theory.md for the proof boundary.
Gates: tests/test_m5a2_affine.py. All public numerical inputs are int/Fraction.
"""
from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction as F


def _q(value):
    if not isinstance(value, (int, F)) or isinstance(value, bool):
        raise ValueError("affine motion requires exact integers or Fractions")
    return F(value)


def _point(point):
    if len(point) != 2:
        raise ValueError("affine motion requires two-dimensional points")
    return tuple(_q(v) for v in point)


def _matrix(matrix):
    if len(matrix) != 2:
        raise ValueError("affine motion requires a 2 by 2 matrix")
    return tuple(_point(row) for row in matrix)


def _apply(matrix, point):
    return tuple(sum(matrix[i][j]*point[j] for j in (0, 1)) for i in (0, 1))


@dataclass(frozen=True)
class AffineFit:
    center: tuple
    translation: tuple
    matrix: tuple
    residuals: tuple

    def __post_init__(self):
        object.__setattr__(self, "center", _point(self.center))
        object.__setattr__(self, "translation", _point(self.translation))
        object.__setattr__(self, "matrix", _matrix(self.matrix))
        residuals = tuple(_point(row) for row in self.residuals)
        if not residuals:
            raise ValueError("affine fit requires a nonempty residual table")
        object.__setattr__(self, "residuals", residuals)

    @property
    def delta(self):
        """Exact maximum coordinate residual; not a physical-path certificate."""
        return max(abs(v) for row in self.residuals for v in row)

    @property
    def endpoint_certificate(self):
        return "EXACT_AFFINE_ENDPOINTS" if self.delta == 0 else "UNCERTIFIED_NONAFFINE_ENDPOINTS"

    def endpoint(self, point):
        point = _point(point)
        mapped = _apply(self.matrix, tuple(point[k]-self.center[k] for k in (0, 1)))
        return tuple(self.center[k]+self.translation[k]+mapped[k] for k in (0, 1))


def fit_affine(start, end):
    """Exact equal-vertex-weight least-squares affine fit, not an L-infinity fit.

    The input ring must span the plane; topology pairing is positional.
    The normal-equation denominator is strictly positive, with no threshold.
    Gate: test_fit_matches_independent_three_point_and_normal_equation_oracles.
    """
    start, end = tuple(map(_point, start)), tuple(map(_point, end))
    if len(start) != len(end) or len(start) < 3:
        raise ValueError("affine fit requires equal vertex counts, at least three")
    center = tuple(sum(p[k] for p in start)/len(start) for k in (0, 1))
    target = tuple(sum(p[k] for p in end)/len(end) for k in (0, 1))
    x = tuple(tuple(p[k]-center[k] for k in (0, 1)) for p in start)
    y = tuple(tuple(p[k]-target[k] for k in (0, 1)) for p in end)
    xx = sum(p[0]*p[0] for p in x)
    xy = sum(p[0]*p[1] for p in x)
    yy = sum(p[1]*p[1] for p in x)
    determinant = xx*yy-xy*xy
    if determinant <= 0:
        raise ValueError("affine fit initial points do not span the plane")
    cross = tuple(tuple(sum(q[i]*p[j] for p, q in zip(x, y)) for j in (0, 1)) for i in (0, 1))
    matrix = tuple(((row[0]*yy-row[1]*xy)/determinant,
                    (row[1]*xx-row[0]*xy)/determinant) for row in cross)
    translation = tuple(target[k]-center[k] for k in (0, 1))
    residuals = tuple(tuple(q[k]-sum(matrix[k][j]*p[j] for j in (0, 1)) for k in (0, 1))
                      for p, q in zip(x, y))
    return AffineFit(center, translation, matrix, residuals)


@dataclass(frozen=True)
class DDAAffineMotion:
    """X=c+s*d+[R(s*u)+s*E](x-c), with E=M-R(u).

    This additive strain arrangement follows b-DDA's finite-rotation endpoint
    update, but u need not recover its internal angle and E need not be symmetric.
    No assumption about non-inversion or the physical interpolant is implicit.
    Gate: test_additive_trajectory_matches_independent_component_oracle.
    """
    matrix: tuple = ((F(1), F(0)), (F(0), F(1)))
    u1: F = F(0)
    translation: tuple = (F(0), F(0))
    center: tuple = (F(0), F(0))

    def __post_init__(self):
        object.__setattr__(self, "matrix", _matrix(self.matrix))
        object.__setattr__(self, "u1", _q(self.u1))
        object.__setattr__(self, "translation", _point(self.translation))
        object.__setattr__(self, "center", _point(self.center))
        if abs(self.u1) > 1:
            raise ValueError("affine rational rotation supports |u1|<=1")

    @property
    def correction(self):
        u = self.u1
        cosine, sine = (1-u*u)/(1+u*u), 2*u/(1+u*u)
        rotation = ((cosine, -sine), (sine, cosine))
        return tuple(tuple(self.matrix[i][j]-rotation[i][j] for j in (0, 1)) for i in (0, 1))

    @property
    def orientation_preserving_sufficient(self):
        """Neumann sufficient condition only; false means unknown, not inversion.

        Gate: test_orientation_sufficient_bound_and_degenerate_counterexample.
        """
        return 2*max(sum(abs(v) for v in row) for row in self.correction) < 1

    def at(self, point, s):
        point, s = _point(point), _q(s)
        if not 0 <= s <= 1:
            raise ValueError("affine time is outside the closed unit window")
        u = s*self.u1
        cosine, sine = (1-u*u)/(1+u*u), 2*u/(1+u*u)
        x, y = tuple(point[k]-self.center[k] for k in (0, 1))
        strain = _apply(self.correction, (x, y))
        return (self.center[0]+s*self.translation[0]+cosine*x-sine*y+s*strain[0],
                self.center[1]+s*self.translation[1]+sine*x+cosine*y+s*strain[1])

    def endpoint(self, point):
        return self.at(point, F(1))

    def corrected_at(self, point, endpoint_residual, s):
        """A specified, endpoint-closing interpolant; NOT an inferred true path.

        Difference from at() is exactly s*residual, hence <=s*delta in L-inf.
        Gate: test_linear_residual_correction_closes_data_without_certification.
        """
        s, residual = _q(s), _point(endpoint_residual)
        value = self.at(point, s)
        return tuple(value[k]+s*residual[k] for k in (0, 1))

src/eab/kernel2d/model_robustness.py:
"""Conservative exact certificates for specified continuous vertex tubes.

These are sufficient conditions, never a complete classifier. Unknown is not
contact and not robustness. Only a singleton, interior VE/EV cover is handled.
See docs/m5b_robustness_theory.md; gates: tests/test_m5b_robustness.py.
All radii are coordinate L-infinity bounds, not inferred physical-path errors.
"""
from fractions import Fraction as F
from math import comb
from .dda_motion import DDAAnchoredMotion


def _q(x):
    if not isinstance(x, (int, F)) or isinstance(x, bool):
        raise ValueError("certificate inputs must be exact rationals")
    return F(x)


def _window(lo, hi):
    lo, hi = _q(lo), _q(hi)
    if not 0 <= lo <= hi <= 1:
        raise ValueError("certificate window must lie in [0,1]")
    return lo, hi


def _add(a, b):
    return tuple((a[i] if i < len(a) else F(0)) +
                 (b[i] if i < len(b) else F(0)) for i in range(max(len(a), len(b))))


def _scale(a, k):
    return tuple(k*x for x in a)


def polynomial_range(coefficients, lo, hi):
    """Exact Bernstein convex-hull enclosure; test_bernstein_independent_oracle."""
    p = tuple(_q(c) for c in coefficients)
    if not p:
        raise ValueError("empty polynomial")
    lo, hi = _window(lo, hi)
    n = len(p)-1
    shifted = tuple((hi-lo)**j*sum(p[k]*comb(k, j)*lo**(k-j)
                                  for k in range(j, n+1)) for j in range(n+1))
    b = tuple(sum(shifted[j]*F(comb(i, j), comb(n, j)) for j in range(i+1))
              for i in range(n+1))
    return min(b), max(b)


def chord_paths(start, end):
    """Coordinate numerator pairs and positive denominator for snapshot P1."""
    if len(start) != len(end) or len(start) < 3:
        raise ValueError("equal rings of at least three vertices required")
    paths = []
    for p, q in zip(start, end):
        if len(p) != 2 or len(q) != 2:
            raise ValueError("two-dimensional points required")
        p, q = tuple(_q(x) for x in p), tuple(_q(x) for x in q)
        paths.append(((p[0], q[0]-p[0]), (p[1], q[1]-p[1]), (F(1),)))
    return tuple(paths)


def dda_paths(start, motion):
    """Adapter to the explicit DDA rational path, not a fit."""
    if type(motion) is not DDAAnchoredMotion:
        raise ValueError("DDAAnchoredMotion required, not an arbitrary callback")
    result = []
    for point in start:
        numerators, denominator = motion.coordinate_polynomials(point)
        result.append((*numerators, denominator))
    return tuple(result)


def _validate(paths):
    if len(paths) < 3:
        raise ValueError("at least three vertex paths required")
    result = []
    for path in paths:
        if len(path) != 3 or any(not p for p in path):
            raise ValueError("expected Nx, Ny, D polynomials")
        path = tuple(tuple(_q(x) for x in p) for p in path)
        if polynomial_range(path[2], 0, 1)[0] <= 0:
            raise ValueError("positive denominator certificate required")
        result.append(path)
    return tuple(result)


def _quotient(numerator, denominator, lo, hi):
    a, b = polynomial_range(numerator, lo, hi), polynomial_range(denominator, lo, hi)
    if b[0] <= 0:
        raise ValueError("positive denominator required")
    values = tuple(x/y for x in a for y in b)
    return min(values), max(values)


def _projection(path, normal, lo, hi, origin):
    numerator = _add(_scale(path[0], normal[0]), _scale(path[1], normal[1]))
    numerator = _add(numerator, _scale(path[2], -origin))
    low, high = _quotient(numerator, path[2], lo, hi)
    return low+origin, high+origin


def _value(path, time):
    return tuple(_quotient(path[k], path[2], time, time)[0] for k in (0, 1))


def _panels(lo, hi, count):
    if not isinstance(count, int) or isinstance(count, bool) or count < 1:
        raise ValueError("positive integer panel count required")
    return tuple((lo+(hi-lo)*F(i, count), lo+(hi-lo)*F(i+1, count)) for i in range(count))


def _normals(a, b):
    normals = [(F(1), F(0)), (F(0), F(1))]
    for paths in (a, b):
        ring = tuple(_value(p, F(0)) for p in paths)
        normals.extend((q[1]-p[1], p[0]-q[0]) for p, q in zip(ring, ring[1:]+ring[:1])
                       if p != q)
    return tuple(normals)


def _radii(ra, rb):
    ra, rb = _q(ra), _q(rb)
    if ra < 0 or rb < 0:
        raise ValueError("tube radii must be nonnegative")
    return ra, rb


def separation_certificate(paths_a, paths_b, radius_a=0, radius_b=0, *,
                           lo=0, hi=1, panels=4):
    """Strict swept projection gap in every panel proves robust no contact.

    Returns None when this sufficient test is inconclusive. The gap is a lower
    bound in coordinate L-infinity distance, not an exact global minimum.
    Gate: test_no_contact_requires_strict_margin_and_covers_whole_window.
    """
    a, b = _validate(paths_a), _validate(paths_b)
    ra, rb = _radii(radius_a, radius_b)
    lo, hi = _window(lo, hi)
    normals, witnesses = _normals(a, b), []
    for lower, upper in _panels(lo, hi, panels):
        best = None
        for normal in normals:
            norm = abs(normal[0])+abs(normal[1])
            anchor = _value(a[0], lower)
            origin = sum(x*y for x, y in zip(anchor, normal))
            aa = tuple(_projection(p, normal, lower, upper, origin) for p in a)
            bb = tuple(_projection(p, normal, lower, upper, origin) for p in b)
            gap = max(min(x[0] for x in bb)-max(x[1] for x in aa),
                      min(x[0] for x in aa)-max(x[1] for x in bb))/norm
            if gap > ra+rb and (best is None or gap > best["gap_lower"]):
                best = dict(window=(lower, upper), normal=normal, gap_lower=gap)
        if best is None:
            return None
        witnesses.append(best)
    return dict(kind="ROBUST_NO_CONTACT", radius_sum=ra+rb,
                gap_lower=min(w["gap_lower"] for w in witnesses), witnesses=tuple(witnesses))


def _minus(a, b):
    return a[0]-b[1], a[1]-b[0]


def _times(a, b):
    p = tuple(x*y for x in a for y in b)
    return min(p), max(p)


def _plus(a, b):
    return a[0]+b[0], a[1]+b[1]


def _cross(a, b):
    return _minus(_times(a[0], b[1]), _times(a[1], b[0]))


def _dot(a, b):
    return _plus(_times(a[0], b[0]), _times(a[1], b[1]))


def _boxes(paths, lo, hi):
    anchor = _value(paths[0], lo)
    return tuple(tuple(_projection(p, ((1, 0), (0, 1))[k], lo, hi, anchor[k])
                       for k in (0, 1)) for p in paths)


def _diff(a, b):
    return tuple(_minus(x, y) for x, y in zip(a, b))


def _length1(box):
    return sum(max(abs(x), abs(y)) for x, y in box)


def _event(a, b, i, j, ra, rb):
    """Cross and both segment projections with vertex-tube error budgets."""
    u = _diff(b[(j+1) % len(b)], b[j])
    w = _diff(a[i], b[j])
    v = _diff(a[i], b[(j+1) % len(b)])
    du, dw = 2*rb, ra+rb
    error_w = du*_length1(w)+dw*_length1(u)+2*du*dw
    error_v = du*_length1(v)+dw*_length1(u)+2*du*dw
    h = _dot(u, v)
    return _cross(u, w), _dot(u, w), (-h[1], -h[0]), error_w, error_v


def _strict_convex(boxes, radius):
    for j, point in enumerate(boxes):
        following = (j+1) % len(boxes)
        u = _diff(boxes[following], point)
        for k, other in enumerate(boxes):
            if k in (j, following):
                continue
            v = _diff(other, point)
            error = 2*radius*(_length1(u)+_length1(v))+8*radius*radius
            if _cross(u, v)[0] <= error:
                return False
    return True


def swept_axis_bounds(paths, *, lo=0, hi=1):
    """Whole-window coordinate enclosures, useful for cached batch certificates.

    Gate: test_no_contact_requires_strict_margin_and_covers_whole_window.
    """
    paths = _validate(paths)
    lo, hi = _window(lo, hi)
    boxes = _boxes(paths, lo, hi)
    return tuple((min(p[k][0] for p in boxes), max(p[k][1] for p in boxes)) for k in (0, 1))


def _mul_poly(a, b):
    result = [F(0)]*(len(a)+len(b)-1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            result[i+j] += x*y
    return tuple(result)


def _derivative(p):
    return tuple(i*p[i] for i in range(1, len(p))) or (F(0),)


def _event_derivative(a, b, i, j, lo, hi):
    """Exact interval of derivative of the rational line-side function."""
    p, q, r = a[i], b[j], b[(j+1) % len(b)]
    # General denominators, including the independent snapshot chord family.
    ux = _add(_mul_poly(r[0], q[2]), _scale(_mul_poly(q[0], r[2]), -1))
    uy = _add(_mul_poly(r[1], q[2]), _scale(_mul_poly(q[1], r[2]), -1))
    wx = _add(_mul_poly(p[0], q[2]), _scale(_mul_poly(q[0], p[2]), -1))
    wy = _add(_mul_poly(p[1], q[2]), _scale(_mul_poly(q[1], p[2]), -1))
    num = _add(_mul_poly(ux, wy), _scale(_mul_poly(uy, wx), -1))
    den = _mul_poly(_mul_poly(r[2], p[2]), _mul_poly(q[2], q[2]))
    dn = _add(_mul_poly(_derivative(num), den), _scale(_mul_poly(num, _derivative(den)), -1))
    return _quotient(dn, _mul_poly(den, den), lo, hi)


def single_cover_certificate(paths_a, paths_b, label, bracket, radius_a=0,
                             radius_b=0, *, panels=4):
    """Sufficient singleton first-cover identity certificate for CCW convex rings.

    Requires early separation, interior projection, nominal strict crossing,
    robust endpoint signs and exclusion of every competitor until bracket end.
    Certifies identity, NOT an unchanged first time or perturbed derivatives.
    Gate: test_single_cover_certificate_has_independent_closed_form_oracle.
    """
    a, b = _validate(paths_a), _validate(paths_b)
    ra, rb = _radii(radius_a, radius_b)
    lo, hi = _window(*bracket)
    if lo == hi or len(label) != 3 or label[0] not in ("VE", "EV"):
        raise ValueError("strict bracket and singleton VE/EV label required")
    tag, first, second = label
    if tag == "VE":
        p, q, rp, rq, i, j = a, b, ra, rb, first, second
    else:
        p, q, rp, rq, i, j = b, a, rb, ra, second, first
    if not (isinstance(i, int) and isinstance(j, int) and 0 <= i < len(p) and 0 <= j < len(q)):
        raise ValueError("invalid feature indices")
    early = separation_certificate(a, b, ra, rb, lo=0, hi=lo, panels=panels)
    if early is None:
        return None
    begin = _event(_boxes(p, lo, lo), _boxes(q, lo, lo), i, j, rp, rq)
    end = _event(_boxes(p, hi, hi), _boxes(q, hi, hi), i, j, rp, rq)
    if not (begin[0][1] < -begin[3] and end[0][0] > end[3]):
        return None
    derivative = _event_derivative(p, q, i, j, lo, hi)
    if derivative[0] <= 0:
        return None
    margins = []
    for lower, upper in _panels(lo, hi, panels):
        aa, bb = _boxes(a, lower, upper), _boxes(b, lower, upper)
        if not _strict_convex(aa, ra) or not _strict_convex(bb, rb):
            return None
        for pp, qq, rr, ss, kind in ((aa, bb, ra, rb, "VE"), (bb, aa, rb, ra, "EV")):
            for ii in range(len(pp)):
                for jj in range(len(qq)):
                    key = (kind, ii, jj) if kind == "VE" else (kind, jj, ii)
                    f, g, h, ew, ev = _event(pp, qq, ii, jj, rr, ss)
                    if key == tuple(label):
                        margin = min(g[0]-ew, h[0]-ev)
                    else:
                        # A line-side or either segment projection may exclude
                        # an incidence. Do not confuse line crossing with contact.
                        margin = max(f[0]-ew, -f[1]-ew, -g[1]-ew, -h[1]-ev)
                    if margin <= 0:
                        return None
                    margins.append(margin)
    return dict(kind="ROBUST_SINGLE_FIRST_COVER", label=tuple(label), bracket=(lo, hi),
                radius_sum=ra+rb, early=early, derivative_lower=derivative[0],
                event_margin_lower=min(margins),
                endpoints_margin=min(-begin[0][1]-begin[3], end[0][0]-end[3]))

src/eab/contact_record.py:
"""ContactRecord：六种现有接触表示的公共契约。

字段按生命周期分四组（设计文档 §四）：
  身份（跨步不变）  block_a/block_b, cover, feature_a/feature_b, joint_material
  步内冻结          ref_points, normal, length_or_area, params
  状态（迭代内演化）mode, mode_prev, entrance_index, gap, shear, normal_force
  转移（跨步携带）  mode_init, gap_ref, slip_ref, bond_flag, lock_position

设计要点：
- 统一词汇（CoverType / Mode）+ 各引擎原始码**同时保留**（raw_mode / raw_cover），
  因为三家的 "3" 含义不同：b-DDA 3 = v-v 第二参考闭合，bdda3d 3 = 键合，tf.cpp 3 = 受拉。
- `extra` 装下一切不入正式字段的列，读取器**不许丢信息**。
- 典范序键 `canonical_key()` 与来源的枚举顺序无关（块序交换不变），用于跨引擎集合同构比较。
  它的分辨率取决于来源给了多少特征身份（审查 C20）：bdda3d 逐步唯一；bdda_df 在旧夹具唯一，
  M4 的 v01/v02 四例首步却有 9 条主特征重复，须另记 multiplicity/第二参考，不能无声去重；
  tf 探针不带特征，键只到 (块对, 盖类) 级；bdda_df 缺 verts.csv 时块号未知的记录同样只到块对级。
  bdda_df 的顶点号在有 verts.csv 时已经 alias 规范化到载入后的多边形（G6 minor 30），与由同一多边形造出的
  内核盖同名；缺 verts.csv 时是原始号。bdda_df 的 VV 顶点来自两组三点参考的共享顶点，不是固定 p1/p2
  （tests/test_m4_bdda_vv_reader.py）；半交换只改参考次序，不改顶点身份。bdda3d 的面身份是 legacy 的三角顶点三元组，归约到几何面要几何
  （tools/g2_bdda3d.py），所以跨引擎比较 bdda3d 仍须经那一步，不能直接比 canonical_key。
  这几条由 tests/test_readers_roundtrip.py 在真实夹具上断言。
"""

from __future__ import annotations

import json
import math
from dataclasses import dataclass, field, fields
from enum import Enum
from typing import Any, Iterable

from .readers.numeric_decode import scalar as scalar_rational
from .readers.numeric_decode import decode_tree, integer, loads as loads_exact


class CoverType(str, Enum):
    """∂E(A,B) 的盖类型（方向无关；谁属于哪块记在 feature_a/feature_b）。"""

    VE = "VE"          # 2D 顶点-边
    VV = "VV"          # 2D 顶点-顶点（∂E 的顶点，法向集值点）
    VF = "VF"          # 3D 顶点-面（facet 盖）
    EE = "EE"          # 3D 交叉棱-棱（facet 盖）
    VE3 = "VE3"        # 3D 顶点-棱（∂E 的棱）
    VV3 = "VV3"        # 3D 顶点-顶点（∂E 的顶点）
    FF = "FF"          # 3D 退化：平行贴面
    FE = "FE"          # 3D 退化：棱平行于面
    EE_PAR = "EE_PAR"  # 3D 退化：平行棱-棱
    NN = "NN"          # tf.cpp 候选类 0（入口展开前）
    NE = "NE"          # tf.cpp 候选类 1（入口展开前）
    UNKNOWN = "UNKNOWN"


class Mode(str, Enum):
    OPEN = "OPEN"
    SLIDING = "SLIDING"
    LOCKED = "LOCKED"
    BONDED = "BONDED"        # bdda3d 键合态
    TENSION = "TENSION"      # tf.cpp 受拉态
    VV_CLOSED = "VV_CLOSED"  # b-DDA v-v 第二参考闭合（m0=3）
    UNVERIFIED = "UNVERIFIED"  # 引擎给了码、也有名字，但归入统一词汇的依据未核实（原始码见 raw_mode）
    UNKNOWN = "UNKNOWN"


# 各引擎状态码 → 统一词汇。原始码另存 raw_mode，映射不可逆时靠 raw 还原。
BDDA_MODE: dict[int, Mode] = {0: Mode.OPEN, 1: Mode.SLIDING, 2: Mode.LOCKED, 3: Mode.VV_CLOSED}
BDDA3D_MODE: dict[int, Mode] = {0: Mode.OPEN, 1: Mode.SLIDING, 2: Mode.LOCKED, 3: Mode.BONDED}
# tf.cpp 注释（tf.cpp:306-313）：0 open 1 friction 2 s-spring 3 t-tension 4 2f-friction 5 2f-lock 6 top-lock
# 4/5/6 此前折进 SLIDING/LOCKED，但 docs/sibling_observations.md 没有为这几个码记下任何 tf.cpp 行号引文
# （"2f"/"top" 的语义、它们在开闭迭代里是否等价于滑动/锁定，都没人核实过）——审查盲区 5。
# 所以标 UNVERIFIED，不替 tf.cpp 断言；raw_mode 保留原始码。入库夹具只出现 1、2（tests/test_tf_reader.py）。
TF_MODE: dict[int, Mode] = {0: Mode.OPEN, 1: Mode.SLIDING, 2: Mode.LOCKED, 3: Mode.TENSION,
                            4: Mode.UNVERIFIED, 5: Mode.UNVERIFIED, 6: Mode.UNVERIFIED}
# tf.cpp c[i][2] / m[j][2]：0 n-n 1 n-e 2 n-p 3 e-e（tf.cpp:297-300, 329-336）
TF_COVER: dict[int, CoverType] = {0: CoverType.NN, 1: CoverType.NE, 2: CoverType.VF, 3: CoverType.EE}
# b-DDA mtype：0 v-e 1 v-v（df05）
BDDA_COVER: dict[int, CoverType] = {0: CoverType.VE, 1: CoverType.VV}
# bdda3d etype
BDDA3D_COVER: dict[str, CoverType] = {"np": CoverType.VF, "ee": CoverType.EE}


@dataclass(frozen=True, slots=True)
class Feature:
    """块上的几何特征。index 为来源引擎的局部/全局编号，-1 表示未知。

    verts：来源没有特征编号、只用顶点号指代特征时的身份（**排序后**的顶点号元组，与列出顺序无关）。
    例：bdda3d 的 n-p 入口用宿主块面扇形里的一个三角 (P2,P3,P4) 指代面，没有面号 → index=-1、
    verts=sorted(P2,P3,P4)；e-e 入口的棱 → verts=sorted(两端点)。空元组表示未提供。
    """

    block: int
    kind: str  # "vertex" | "edge" | "face"
    index: int = -1
    verts: tuple[int, ...] = ()

    def as_tuple(self) -> tuple[int, str, int, tuple[int, ...]]:
        return (self.block, self.kind, self.index, self.verts)


Vec = tuple[float, ...]


@dataclass(slots=True)
class ContactRecord:
    # ---- 身份（跨步不变）----
    source: str                 # "bdda-df" | "bdda2" | "bdda3d" | "tf" | "dda4" | "eab"
    step: int
    contact_index: int          # 来源枚举序里的位置（只做映射，不做语义）
    block_a: int
    block_b: int
    cover: CoverType = CoverType.UNKNOWN
    raw_cover: int | str | None = None
    feature_a: Feature | None = None
    feature_b: Feature | None = None
    joint_material: int | None = None
    # ---- 步内冻结 ----
    ref_points: tuple[Vec, ...] = ()
    normal: Vec | None = None
    length_or_area: float | None = None   # 2D 边长 b1 / 3D 面积
    params: Vec = ()                      # 2D (s3,) / 3D (t1, t2)
    # ---- 状态（迭代内演化）----
    mode: Mode = Mode.UNKNOWN
    raw_mode: int | None = None
    mode_prev: Mode | None = None
    raw_mode_prev: int | None = None
    entrance_index: int | None = None
    gap: float | None = None              # 法向间隙/侵入（来源约定：正=张开）
    shear: Vec | None = None
    normal_force: float | None = None
    # ---- 转移（跨步携带）----
    mode_init: Mode | None = None
    raw_mode_init: int | None = None
    gap_ref: float | None = None          # o3t
    slip_ref: Vec | None = None           # o4t / 三维滑移参考
    bond_flag: int | None = None          # m0_0
    lock_position: float | None = None    # c206 写回的 s3（钉定的"泄漏"语义）
    # ---- 溯源与余项 ----
    extra: dict[str, Any] = field(default_factory=dict)

    # 典范序键：与来源枚举顺序无关，用于跨引擎集合同构比较。
    def canonical_key(self) -> tuple:
        a, b = sorted((self.block_a, self.block_b))
        feats = tuple(sorted(f.as_tuple() for f in (self.feature_a, self.feature_b) if f is not None))
        return (a, b, self.cover.value, feats)

    def to_dict(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        for f in fields(self):
            v = getattr(self, f.name)
            out[f.name] = _encode(v)
        return out

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "ContactRecord":
        kw: dict[str, Any] = {}
        for f in fields(cls):
            if f.name not in d:
                continue
            kw[f.name] = _decode(f.name, d[f.name])
        return cls(**kw)


def _encode(v: Any) -> Any:
    if isinstance(v, Enum):
        return v.value
    if isinstance(v, Feature):
        return {"block": v.block, "kind": v.kind, "index": v.index, "verts": list(v.verts)}
    if isinstance(v, tuple):
        return [_encode(x) for x in v]
    if isinstance(v, dict):
        return {k: _encode(x) for k, x in v.items()}
    return v


_TUPLE_FIELDS = {"ref_points", "normal", "params", "shear", "slip_ref"}
_SCALAR_FIELDS = {"length_or_area", "gap", "normal_force", "gap_ref", "lock_position"}
_INTEGER_FIELDS = {"step", "contact_index", "block_a", "block_b", "joint_material",
                   "raw_mode", "raw_mode_prev", "raw_mode_init", "entrance_index", "bond_flag"}


def _decode(name: str, v: Any) -> Any:
    if v is None:
        return None
    if name == "cover":
        return CoverType(v)
    if name in ("mode", "mode_prev", "mode_init"):
        return Mode(v)
    if name in ("feature_a", "feature_b"):
        return Feature(integer(v["block"], f"{name}.block"), str(v["kind"]),
                       integer(v["index"], f"{name}.index"),
                       tuple(integer(x, f"{name}.verts[{i}]") for i, x in enumerate(v.get("verts", ()))))
    if name == "ref_points":
        return tuple(tuple(scalar_rational(x, quantity=f"{name}[{i}][{j}]") for j, x in enumerate(p))
                     for i, p in enumerate(v))
    if name in _TUPLE_FIELDS:
        return tuple(scalar_rational(x, quantity=f"{name}[{i}]") for i, x in enumerate(v))
    if name in _SCALAR_FIELDS:
        return scalar_rational(v, quantity=name)
    if name in _INTEGER_FIELDS or (name == "raw_cover" and not isinstance(v, str)):
        return integer(v, name)
    if name == "extra":
        return decode_tree(v, name)
    return v


def validate(rec: ContactRecord) -> None:
    """契约校验：违反即 ValueError。只校验结构与有限性，不校验物理。"""

    if rec.block_a < 0 or rec.block_b < 0:
        raise ValueError(f"negative block id: {rec.block_a}, {rec.block_b}")
    if rec.step < 0:
        raise ValueError(f"negative step: {rec.step}")
    if not isinstance(rec.cover, CoverType) or not isinstance(rec.mode, Mode):
        raise ValueError("cover/mode must be enums")
    for f in (rec.feature_a, rec.feature_b):
        if f is not None and f.kind not in ("vertex", "edge", "face"):
            raise ValueError(f"bad feature kind: {f.kind}")
        if f is not None and (list(f.verts) != sorted(f.verts) or not all(isinstance(x, int) for x in f.verts)):
            raise ValueError(f"feature verts must be sorted ints: {f.verts}")
    for name in ("gap", "normal_force", "length_or_area", "gap_ref", "lock_position"):
        v = getattr(rec, name)
        if v is not None and not math.isfinite(v):
            raise ValueError(f"non-finite {name}: {v}")
    for name in ("normal", "shear", "slip_ref", "params"):
        v = getattr(rec, name)
        if v is not None and any(not math.isfinite(x) for x in v):
            raise ValueError(f"non-finite {name}: {v}")
    for p in rec.ref_points:
        if any(not math.isfinite(x) for x in p):
            raise ValueError(f"non-finite ref point: {p}")


def records_to_json(records: Iterable[ContactRecord]) -> str:
    return json.dumps([r.to_dict() for r in records], ensure_ascii=False, indent=1, sort_keys=True)


def records_from_json(text: str) -> list[ContactRecord]:
    return [ContactRecord.from_dict(d) for d in loads_exact(text)]

